def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full, uniformly colored rows encode a repeating row pattern.
    uniform = {}
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            uniform[r] = row[0]
    if uniform:
        period = len(uniform)
        by_residue = {r % period: color for r, color in uniform.items()}
        if len(by_residue) == period:
            return [[by_residue[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise, extend the diagonal stripes, using their count as the period.
    coords = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != 0]

    def groups(key_fn):
        result = {}
        for r, c, color in coords:
            k = key_fn(r, c)
            result.setdefault(k, []).append(color)
        return result

    for key_fn in (lambda r, c: r + c, lambda r, c: c - r):
        pass

    candidates = [groups(lambda r, c: r + c), groups(lambda r, c: c - r)]
    strength = [sum(len(v) * (len(v) - 1) for v in g.values()) for g in candidates]
    g = candidates[0] if strength[0] >= strength[1] else candidates[1]

    # Each stripe should have a single color.
    stripes = {k: max(set(v), key=v.count) for k, v in g.items()}
    period = len(stripes)
    by_residue = {k % period: color for k, color in stripes.items()}

    if len(by_residue) != period:
        # Fallback: retain the observed stripe assignment by residue.
        by_residue = {k % period: color for k, color in stripes.items()}

    key_fn = (lambda r, c: r + c) if strength[0] >= strength[1] else (lambda r, c: c - r)
    return [[by_residue[key_fn(r, c) % period] for c in range(w)] for r in range(h)]
